"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["13963"],{89394(e){e.exports=JSON.parse('{"id":"F148","slug":"treasury-stock-method","name":"Treasury Stock Method (Diluted Shares)","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Stock-based compensation","level":"Intermediate","aliases":["diluted EPS","stock options dilution","in the money options","TSM"],"formula":{"latex":"\\\\text{Net new shares}=N_{opt}\\\\left(1-\\\\frac{K}{P}\\\\right)","also":[],"text":"If options are in the money, Net new shares = Options x (1 - Strike / Share price); Diluted shares = Basic shares + Net new shares"},"symbols":[{"symbol":"N_opt","meaning":"Number of options outstanding","unit":"number"},{"symbol":"K","meaning":"Strike (exercise) price","unit":"money"},{"symbol":"P","meaning":"Current share price","unit":"money"}],"when_to_use":"Use it to count the extra shares from stock options in diluted EPS and valuation. It assumes the exercise proceeds are used to buy back shares at the market price, so only the net new shares count. Options with a strike above the share price are ignored.","worked_example":{"problem":"A company has 20 million basic shares and 1 million options with a strike of 30. The share price is 45 and net income is 90 million.","inputs":{"basic":20,"opts":1,"k":30,"p":45,"ni":90},"steps":[{"label":"Proceeds if exercised = options x strike (0 if out of the money)","working":"1 x 30 if 45>30 else 0","value":"30.00"},{"label":"Shares bought back = proceeds / price","working":"30 / 45","value":"0.667"},{"label":"Net new shares = options - shares bought back (0 if out of the money)","working":"1-0.666667 if 45>30 else 0","value":"0.333"},{"label":"Diluted shares = basic + net new","working":"20+0.333333","value":"20.333"},{"label":"Basic EPS","working":"90 / 20","value":"4.50"},{"label":"Diluted EPS","working":"90 / 20.3333","value":"4.43"}],"answer":"Exercise would bring in 30.00 million, which buys back 0.667 million shares. Net new shares are 0.333 million, so diluted shares are 20.333 million. EPS falls from 4.50 to 4.43."},"calculator":{"available":true,"inputs":[{"id":"basic","label":"Basic shares (millions)","unit":"number","type":"number","default":20,"hint":""},{"id":"opts","label":"Options outstanding (millions)","unit":"number","type":"number","default":1,"hint":""},{"id":"k","label":"Strike price","unit":"money","type":"number","default":30,"hint":""},{"id":"p","label":"Share price","unit":"money","type":"number","default":45,"hint":""},{"id":"ni","label":"Net income (millions)","unit":"money","type":"number","default":90,"hint":""}],"checks":[{"expr":"p>0 and basic>0","message":"The share price and the basic shares must be above zero."}],"steps":[{"id":"proceeds","label":"Proceeds if exercised = options x strike (0 if out of the money)","expr":"opts*k if p>k else 0","format":"num2"},{"id":"bought","label":"Shares bought back = proceeds / price","expr":"proceeds/p","format":"num3"},{"id":"net","label":"Net new shares = options - shares bought back (0 if out of the money)","expr":"opts-bought if p>k else 0","format":"num3"},{"id":"dil","label":"Diluted shares = basic + net new","expr":"basic+net","format":"num3"},{"id":"eps_b","label":"Basic EPS","expr":"ni/basic","format":"money"},{"id":"eps_d","label":"Diluted EPS","expr":"ni/dil","format":"money"}],"results":["dil","eps_d"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"proceeds":30,"bought":0.6666666666666666,"net":0.33333333333333337,"dil":20.333333333333332,"eps_b":4.5,"eps_d":4.426229508196721}},"finder":{"finds":"Diluted share count and EPS from options","needs":"Basic shares, options, strike, share price, net income"},"related":[{"slug":"eps","name":"Earnings per Share (EPS)"},{"slug":"dilution-from-new-issue","name":"Ownership Dilution from a New Share Issue"},{"slug":"warrant-value-dilution","name":"Warrant Value with Dilution"}],"related_ids":["F064","F186","F348"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Net\xa0new\xa0shares</mtext><mo>=</mo><msub><mi>N</mi><mrow><mi>o</mi><mi>p</mi><mi>t</mi></mrow></msub><mrow><mo fence=\\"true\\">(</mo><mn>1</mn><mo>\u2212</mo><mfrac><mi>K</mi><mi>P</mi></mfrac><mo fence=\\"true\\">)</mo></mrow></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Net new shares}=N_{opt}\\\\left(1-\\\\frac{K}{P}\\\\right)</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mtext>Net\xa0new\xa0shares</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\text{Net new shares}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><msub><mi>N</mi><mrow><mi>o</mi><mi>p</mi><mi>t</mi></mrow></msub><mrow><mo fence=\\"true\\">(</mo><mn>1</mn><mo>\u2212</mo><mfrac><mi>K</mi><mi>P</mi></mfrac><mo fence=\\"true\\">)</mo></mrow></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =N_{opt}\\\\left(1-\\\\frac{K}{P}\\\\right)</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"tranche-loss","name":"Tranche Loss Allocation (Attachment and Detachment)"},"next":{"slug":"trend-index-analysis","name":"Trend Analysis: Index and Growth Rates"},"lesson":null,"total":522}')}}]);